import { Image } from 'expo-image';
import { View } from 'react-native';

// The bundled seal (generated by `npm run branding`): the built-in logo, shown offline too.
// Its navy ring is transparent outside, so it sits on a white disc with a hairline ring to
// stay visible on the dark background.
const SEAL = require('@/assets/branding/splash-icon.png') as number;

type Props = {
  /** Outer size of the disc, in px. */
  size: number;
  /** Set where the seal stands alone; omit where the app name sits next to it (decorative). */
  accessibilityLabel?: string;
};

export function Seal({ size, accessibilityLabel }: Props) {
  // About 4% padding inside the disc (4 px at 104 px), at least 1 px.
  const pad = Math.max(1, Math.round(size * 0.04));
  const inner = size - pad * 2;
  return (
    <View
      accessible={!!accessibilityLabel}
      accessibilityRole={accessibilityLabel ? 'image' : undefined}
      accessibilityLabel={accessibilityLabel}
      importantForAccessibility={accessibilityLabel ? 'yes' : 'no-hide-descendants'}
      style={{ width: size, height: size, borderRadius: size / 2 }}
      className="items-center justify-center border border-hairline bg-white"
    >
      <Image source={SEAL} style={{ width: inner, height: inner }} contentFit="contain" accessibilityIgnoresInvertColors />
    </View>
  );
}
